{
  "implementation": "def solve(case):
    threshold = case['threshold']
    accepted = []
    diagnostics = []
    for c in case['calls']:
        cid = c['call_id']
        gain = c['loss_without_call'] - c['loss_with_call']
        tokens = c['prediction_tokens']
        if tokens > 0:
            norm = gain / tokens
        else:
            norm = 0.0
        norm = round(norm, 8)
        acc = c['parseable'] and norm >= threshold
        diagnostics.append({'call_id': cid, 'accepted': acc, 'normalized_gain': norm})
        if acc:
            accepted.append(cid)
    return {'accepted_call_ids': accepted, 'diagnostics': diagnostics}"
}
